c=collections.Counter()
ex={}
for i,line in enumerate(open(f,errors='replace')):
    if i<START: continue
    try:r=json.loads(line)
    except Exception: continue
    t=r.get('type')
    key=t
    if t=='attachment':
        key=('attachment',(r.get('attachment') or {}).get('type'))
    if t=='user':
        m=r['message']; cont=m.get('content')
