            key=('user','list:'+','.join(sorted(set(b.get('type','?') for b in cont))))
        else: key=('user','str')
    if t=='assistant':
        cont=r['message'].get('content')
        key=('assistant',','.join(sorted(set(b.get('type','?') for b in cont))) if isinstance(cont,list) else 'str')
    c[key]+=1
    ex.setdefault(key,i)
for k,v in sorted(c.items(),key=lambda x:-x[1]): print(v,k,ex[k])
EOF

