                              cc=u.get('cache_creation_input_tokens', 0), out=u.get('output_tokens', 0), text_chars=0, tool_chars=0, tools=[], texts=[]))
        c = calls[callidx[mid]]
        c['out'] = max(c['out'], u.get('output_tokens', 0))
        for b in m['content']:
            if b.get('type') == 'text': c['text_chars'] += len(b['text']); c['texts'].append(b['text'])
            elif b.get('type') == 'tool_use':
                c['tool_chars'] += len(json.dumps(b.get('input', {})))
                c['tools'].append(b['name'])
                tooluse[b['id']] = (b['name'], b.get('input', {}), callidx[mid])
    elif t == 'user':
        cont = r['message'].get('content')
        after = len(calls) - 1
        if isinstance(cont, str):
            if cont.startswith('Another Claude session sent a message'): src = 'hand-back'
            elif cont.startswith('<task-notification>'): src = 'notification (remote, ReadNotifications cue)'
            elif cont.startswith('<system-reminder>') or cont.startswith('(Re-invocation') or cont.startswith('<local-command') or cont.startswith('<command-name>'): src = 'harness'
            elif cont.startswith('This session is being continued'): src = 'compaction summary'
            else: src = 'curator'
            items.append(dict(after=after, ts=ts, line=ln, src=src, chars=len(cont), label=cont[:70].replace('\n', ' '), full=cont if src == 'curator' else None))
        else:
            for b in cont:
                if b.get('type') == 'tool_result':
                    name, inp, ci = tooluse.get(b['tool_use_id'], ('?', {}, -1))
                    src = name
                    if name == 'ArtifactComments': src = 'ArtifactComments ' + inp.get('action', '?')
                    cc = b.get('content')
                    txt = cc if isinstance(cc, str) else '\n'.join(x.get('text', '') for x in (cc or []) if x.get('type') == 'text')
                    items.append(dict(after=after, ts=ts, line=ln, src=src, chars=tlen(cc), label=(name + ' ' + json.dumps(inp)[:90]), text=txt, name=name, inp=inp, tid=b['tool_use_id']))
                elif b.get('type') == 'image':
                    items.append(dict(after=after, ts=ts, line=ln, src='curator (image)', chars=len(json.dumps(b)), label='image'))
                elif b.get('type') == 'text':
                    src = 'curator' if not b['text'].startswith(('Base directory', '<system-reminder>')) else 'Skill load text'
                    items.append(dict(after=after, ts=ts, line=ln, src=src, chars=len(b['text']), label=b['text'][:70].replace('\n', ' '), full=b['text'] if src == 'curator' else None))
    elif t == 'attachment':
        a = r['attachment']; at = a['type']
        rend = r.get('rendered')
        chars = sum(len(x.get('content', '')) if isinstance(x.get('content'), str) else len(json.dumps(x)) for x in rend) if rend else 0
        after = len(calls) - 1
        if at == 'queued_command':
            kind = (a.get('origin') or {}).get('kind')
            p = a.get('prompt') if isinstance(a.get('prompt'), str) else ''
            if kind == 'peer': src = 'hand-back'
            elif kind == 'human': src = 'curator'
            else: src = 'notification (agent finished)'
            items.append(dict(after=after, ts=ts, line=ln, src=src, chars=chars, label=p[:70].replace('\n', ' '), full=p if src == 'curator' else None))
        elif at == 'file':
            items.append(dict(after=after, ts=ts, line=ln, src='attachment file', chars=chars, label=a.get('filename', '')))
        elif at in ('total_tokens_reminder', 'task_reminder', 'silent_turn_reminder', 'deferred_tools_delta', 'mcp_instructions_delta', 'skill_listing', 'agent_listing_delta', 'invoked_skills', 'instructions', 'environment', 'session_context', 'date', 'model', 'hook_additional_context', 'remote_session_change', 'auto_mode', 'compact_file_reference', 'pdf_reference', 'inlined_image_paths'):
            items.append(dict(after=after, ts=ts, line=ln, src='reminder: ' + at, chars=chars, label=at))
        # prompt_snapshot, deferred_tools_record, batching_reminder_sent, hook_success, command_permissions, credential_org: not rendered into context

# ---------- growth per interval
for k, c in enumerate(calls):
    c['inc'] = []   # items arriving after this call and before the next
for it in items:
    if it['after'] >= 0: calls[it['after']]['inc'].append(it)
base_items = [it for it in items if it['after'] < 0]
neg = 0
for k, c in enumerate(calls):
    if k + 1 < len(calls):
        c['delta'] = calls[k + 1]['ctx'] - c['ctx']
        c['own'] = min(c['out'], max(c['delta'], 0))
        c['rest'] = c['delta'] - c['own']
        if c['delta'] < 0: neg += 1
        tot = sum(i['chars'] for i in c['inc'])
        for i in c['inc']:
            i['tok'] = c['rest'] * i['chars'] / tot if tot else 0
    else:
        c['delta'] = None; c['own'] = c['out']; c['rest'] = 0
        for i in c['inc']: i['tok'] = None

def hhmm(ts): return ts[5:16].replace('T', ' ')
def K(n): return f'{n/1000:.1f}K' if abs(n) >= 1000 else f'{n:.0f}'
